package com.project7.localmanager;
import android.content.Context;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Same connection seen-set admission; no invented persistent session identity. */
public final class WishGateway {
 private static final String METHOD="setChooseTreasure",ANIMATION="setWishGroupAnimPlayed";
 private static final Method WRITE=BaiyeTransactions.Access.method(LocalGatewayServer.class,"writeFrame",void.class,false,OutputStream.class,int.class,byte[].class),CALLBACK=BaiyeTransactions.Access.method(LocalGatewayServer.class,"completeCallback",void.class,false,OutputStream.class,byte[].class,int.class,String.class),REFRESH=BaiyeTransactions.Access.method(LocalGatewayServer.class,"refreshResourceProfile",void.class,false,byte[].class,String.class,LocalTutorialStore.Progress.class,LocalEventEngine.class);
 private WishGateway(){}
 public static void prepare(Context context)throws IOException{WishCatalog.prepare(context);try{WishDrawPolicy.prepare();}catch(Exception e){throw new IOException("许愿抽卡初始化失败",e);}}
 /** Pure one-time migration/projection. Never a draw, reward or new profile owner. */
 public static byte[] prepareProfile(byte[] before)throws IOException{WishCatalog.ready();BaiyeTransactions.document(before);SharedUpState state=SharedUpState.read(before);byte[]after=BsonLite.withProfileDocument(before,SharedUpState.KEY,state.canonical);byte[]ldd=BsonLite.documentValue(after,"ldd");if(ldd==null)ldd=BsonLite.EMPTY_DOCUMENT;ldd=WishChoosePolicy.pair(ldd,"iuc",1,WishProbability.projected(state.failures));after=BsonLite.withProfileDocument(after,"ldd",ldd);byte[]left=BsonLite.withoutProfileKey(before,SharedUpState.KEY),right=BsonLite.withoutProfileKey(after,SharedUpState.KEY),old=BsonLite.documentValue(before,"ldd");if(old==null)right=BsonLite.withoutProfileKey(right,"ldd");else{left=BsonLite.withProfileDocument(left,"ldd",BsonLite.withoutProfileKey(old,"iuc"));right=BsonLite.withProfileDocument(right,"ldd",BsonLite.withoutProfileKey(ldd,"iuc"));}WishCatalog.need(Arrays.equals(left,right),"startup mutation ownership");return after;}
 private static void stopped(java.util.function.BooleanSupplier cancelled)throws IOException{if(cancelled==null||cancelled.getAsBoolean()||Thread.currentThread().isInterrupted())throw new IOException("Wish startup cancelled");try{FullCollectionInitializer.requireStopped();}catch(IOException e){throw e;}catch(Exception e){throw new IOException("Wish startup requires stopped original owner",e);}}
 public static void prepareStoppedProfile(Object exactStore,String account,int uid,java.util.function.BooleanSupplier cancelled)throws IOException{
  exactStore=unwrapProvider(exactStore);
  if(exactStore==null||exactStore.getClass()!=LocalProfileStore.class||account==null||!account.matches("[a-zA-Z0-9_.-]{1,128}")||account.equals(".")||account.equals("..")||uid<=0||LocalAccountStore.isTemplateAccount(account))throw new IOException("Wish startup identity");
  try{synchronized(exactStore){synchronized(BaiyeTransactions.Access.LOCK.get(null)){stopped(cancelled);File dir=((File)BaiyeTransactions.Access.DIR.get(exactStore)).getCanonicalFile(),file=new File(dir,account+".bson");if(!dir.isDirectory()||!dir.getAbsoluteFile().equals(dir.getCanonicalFile())||!file.isFile()||!file.getAbsoluteFile().equals(file.getCanonicalFile())||!file.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile()))throw new IOException("Wish startup profile path");byte[]before=(byte[])BaiyeTransactions.call(BaiyeTransactions.Access.READ,null,file);if(!account.equals(BsonLite.stringValue(before,"account"))||!account.equals(BsonLite.stringValue(before,"an"))||!Integer.valueOf(uid).equals(BsonLite.intValue(before,"uid")))throw new IOException("Wish startup bound identity");byte[]candidate=prepareProfile(before);stopped(cancelled);if(!Arrays.equals(before,(byte[])BaiyeTransactions.call(BaiyeTransactions.Access.READ,null,file)))throw new IOException("Wish startup profile changed");if(!Arrays.equals(before,candidate)){File temp=new File(dir,file.getName()+".tmp");if(!temp.getAbsoluteFile().equals(temp.getCanonicalFile())||temp.exists()&&!temp.isFile())throw new IOException("Wish startup temporary path");try{BaiyeTransactions.call(BaiyeTransactions.Access.WRITE,null,file,candidate);}catch(IOException|RuntimeException error){byte[]observed;try{observed=(byte[])BaiyeTransactions.call(BaiyeTransactions.Access.READ,null,file);}catch(Exception uncertain){throw new BaiyeTransactions.UncertainCommit();}if(!Arrays.equals(observed,candidate)){if(Arrays.equals(observed,before))throw error;throw new BaiyeTransactions.UncertainCommit();}}}stopped(cancelled);if(!Arrays.equals(candidate,(byte[])BaiyeTransactions.call(BaiyeTransactions.Access.READ,null,file)))throw new BaiyeTransactions.UncertainCommit();}}}catch(IllegalAccessException e){throw new IOException(e);}
 }
 public static boolean handleSequencedRequest(LocalGatewayServer g,OutputStream out,byte[]eid,String method,byte[]params,Integer callback,String account,LocalTutorialStore.Progress progress,LocalEventEngine engine,Integer sequence,Set<Integer>seen)throws IOException{
  if(ANIMATION.equals(method)){if(callback!=null&&callback<=0){publish(g,out,eid,message("请求回调无效，本次操作未提交。"),null);return true;}animation(g,out,eid,params,callback,account);return true;}
  if(!METHOD.equals(method))return false;
  if(callback!=null&&callback<=0){publish(g,out,eid,rejected(1882,"请求回调无效，本次改选未提交。"),null);return true;}
  if(sequence==null||sequence<0||seen==null){publish(g,out,eid,rejected(1882,"请求序号无效，请重新操作。"),callback);return true;}
  synchronized(seen){if(!seen.add(sequence))return true;} // Caller already sent reliable ACK. No second unsequenced typed reply.
  LocalResourceEngine.Result r;boolean committed=false;
  try{Object owner=unwrapProvider(BaiyeTransactions.Access.PROVIDER.get(g));if(owner==null||owner.getClass()!=LocalProfileStore.class)throw new IllegalArgumentException("owner");r=BaiyeTransactions.transact((LocalProfileStore)owner,account,(before,resources)->WishChoosePolicy.apply(before,resources,params));committed=true;}
  catch(BaiyeTransactions.UncertainCommit uncertain){throw uncertain;}
  catch(IllegalAccessException error){throw new IOException(error);}
  catch(RuntimeException|IOException rejected){int code=rejected instanceof WishChoosePolicy.Rejected?((WishChoosePolicy.Rejected)rejected).code:1882;r=rejected(code,"本次许愿改选未提交，请检查目标、钻石及未揭卡组后重试。");}
  if(committed&&engine!=null)synchronized(engine){BaiyeTransactions.call(REFRESH,g,BaiyeGateway.digest(METHOD),account,progress,engine);}
  publish(g,out,eid,r,callback);return true;
 }
 public static boolean handleDirect(LocalGatewayServer g,OutputStream out,byte[]eid,byte[]digest,byte[]params,String account,LocalTutorialStore.Progress progress,LocalEventEngine engine)throws IOException{if(Arrays.equals(digest,BaiyeGateway.digest(ANIMATION))){Integer cb=null;try{if(BsonLite.keys(params).contains("_cbid_"))cb=BaiyeTransactions.positive(BsonLite.numericValue(params,"_cbid_"));}catch(RuntimeException bad){publish(g,out,eid,message("祈愿动画状态未提交。"),null);return true;}animation(g,out,eid,params,cb,account);return true;}if(!Arrays.equals(digest,BaiyeGateway.digest(METHOD)))return false;publish(g,out,eid,rejected(1882,"请通过许愿界面重新发起可靠请求。"),null);return true;}
 public static boolean handleRequest(LocalGatewayServer g,OutputStream out,byte[]eid,String method,byte[]params,Integer callback,String account,LocalTutorialStore.Progress progress,LocalEventEngine engine)throws IOException{if(ANIMATION.equals(method)){if(callback!=null&&callback<=0){publish(g,out,eid,message("请求回调无效，本次操作未提交。"),null);return true;}animation(g,out,eid,params,callback,account);return true;}if(!METHOD.equals(method))return false;publish(g,out,eid,rejected(1882,"请求缺少连接序号，请重新操作。"),callback);return true;}
 private static void animation(LocalGatewayServer g,OutputStream out,byte[]eid,byte[]params,Integer callback,String account)throws IOException{LocalResourceEngine.Result result;try{Object owner=unwrapProvider(BaiyeTransactions.Access.PROVIDER.get(g));if(owner==null||owner.getClass()!=LocalProfileStore.class)throw new IllegalArgumentException("owner");result=BaiyeTransactions.transact((LocalProfileStore)owner,account,(before,resources)->WishAnimationPolicy.apply(before,resources,params));}catch(BaiyeTransactions.UncertainCommit e){throw e;}catch(IllegalAccessException e){throw new IOException(e);}catch(IOException|RuntimeException e){result=message("祈愿动画状态未提交，请重新打开界面同步。 ");}for(LocalResourceEngine.Reply f:result.replies)BaiyeTransactions.call(WRITE,g,out,5,ProtoLite.entityMessage(eid,BaiyeGateway.digest(f.method),f.parameters));if(callback!=null&&callback>0)BaiyeTransactions.call(CALLBACK,g,out,eid,callback.intValue(),ANIMATION);}
 static LocalResourceEngine.Result message(String text){LocalResourceEngine.Result r=new LocalResourceEngine.Result(BsonLite.EMPTY_DOCUMENT);r.add("showMessageStr",BsonLite.document("m",text));return r;}
 static LocalResourceEngine.Result rejected(int code,String message){LocalResourceEngine.Result r=new LocalResourceEngine.Result(BsonLite.EMPTY_DOCUMENT);r.add("showMessageStr",BsonLite.document("m",message));r.add("replySetChooseTreasure",BsonLite.document("r",code,"t",5,"i",Collections.emptyList()));return r;}
 static void publish(LocalGatewayServer g,OutputStream out,byte[]eid,LocalResourceEngine.Result r,Integer callback)throws IOException{for(LocalResourceEngine.Reply f:r.replies)BaiyeTransactions.call(WRITE,g,out,5,ProtoLite.entityMessage(eid,BaiyeGateway.digest(f.method),f.parameters));if(callback!=null&&callback>0)BaiyeTransactions.call(CALLBACK,g,out,eid,callback.intValue(),METHOD);}
 private static Object unwrapProvider(Object provider){if(provider==null||!"FailureSafeProfileProvider".equals(provider.getClass().getSimpleName()))return provider;try{java.lang.reflect.Method m=provider.getClass().getDeclaredMethod("delegate");m.setAccessible(true);Object d=m.invoke(provider);if(d!=null)return d;}catch(Exception ignored){}return provider;}
}
